/* @lc app=leetcode id=1970 lang=kotlin */
class Solution { fun latestDayToCross(row: Int, col: Int, cells: Array<IntArray>): Int = (row * col + 2).let { n -> IntArray(n) { it }.let { parent -> IntArray(n).let { grid -> (object : (Int) -> Int { override fun invoke(i: Int): Int = if (parent[i] == i) i else invoke(parent[i]).also { parent[i] = it } }).let { find -> { i: Int, j: Int -> find(i).let { rI -> find(j).let { rJ -> if (rI != rJ) parent[rI] = rJ } } }.let { union -> (cells.size - 1 downTo 0).first { i -> cells[i].let { cell -> (cell[0] - 1).let { r -> (cell[1] - 1).let { c -> (r * col + c + 1).let { id -> grid[id] = 1.also { if (r > 0 && grid[id - col] == 1) union(id, id - col) }.also { if (r < row - 1 && grid[id + col] == 1) union(id, id + col) }.also { if (c > 0 && grid[id - 1] == 1) union(id, id - 1) }.also { if (c < col - 1 && grid[id + 1] == 1) union(id, id + 1) }.also { if (r == 0) union(0, id) }.also { if (r == row - 1) union(n - 1, id) } }.run { find(0) == find(n - 1) } } } } } } } } } }